import { A as ALLAUTH_API_URL } from "../../../../chunks/constants.js";
import { l as loginSchema } from "../../../../chunks/schemas.js";
import { redirect, fail } from "@sveltejs/kit";
import "@sveltejs/kit/internal";
import "../../../../chunks/exports.js";
import "../../../../chunks/utils.js";
import "@sveltejs/kit/internal/server";
import "../../../../chunks/state.svelte.js";
import "../../../../chunks/formData.js";
import { s as superValidate, a as setError } from "../../../../chunks/superValidate.js";
import "../../../../chunks/string.js";
import { z as zod } from "../../../../chunks/zod.js";
const load = async ({ fetch, request, locals }) => {
  if (locals.user) {
    redirect(302, "/admin");
  }
  const form = await superValidate(request, zod(loginSchema));
  return { form, title: "WathbahGRC Admin" };
};
const actions = {
  login: async ({ request, fetch, cookies, url }) => {
    const form = await superValidate(request, zod(loginSchema));
    if (!form.valid) {
      return fail(400, { form });
    }
    const email = form.data.username;
    const password = form.data.password;
    const login = {
      email,
      password
    };
    const endpoint = `${ALLAUTH_API_URL}/auth/login`;
    const requestInitOptions = {
      method: "POST",
      body: JSON.stringify(login)
    };
    const res = await fetch(endpoint, requestInitOptions).then((res2) => res2.json());
    if (res.status !== 200) {
      console.error(res);
      if (res.errors) {
        res.errors.forEach((error) => {
          setError(form, error.param, error.code);
        });
        return fail(res.status, { form });
      }
      return fail(res.status || 400, { form });
    }
    cookies.set("token", res.meta.access_token, {
      httpOnly: true,
      sameSite: "lax",
      path: "/",
      secure: true
    });
    cookies.set("allauth_session_token", res.meta.session_token, {
      httpOnly: true,
      sameSite: "lax",
      path: "/",
      secure: true
    });
    redirect(302, "/admin");
  }
};
export {
  actions,
  load
};
